function mouseclick(d) {
    var items = new Array();
             Shiny.onInputChange("mydata", d.name <http://d.name>);
             $(document).ready(function() {
                      Shiny.addCustomMessageHandler("testmessage",
                                        function(message) {

                                                for(var i =0; i < message.value.length; i ++){
                                                        items.push(message.value[i]);
                                                }
                                        alert(items);
                                        });
                                });
                                alert(items);
}
</script>

